+	function localProfileUrlPath(url) {
+		const prefix = '/assets/uploads/profile/';
+		const relativePrefix = `${nconf.get('relative_path') || ''}${prefix}`;
+		if (typeof url !== 'string') {
+			return false;
+		}
+		const matchingPrefix = [relativePrefix, prefix].find(value => url.startsWith(value));
+		if (!matchingPrefix) {
+			return false;
+		}
+		const filename = url.slice(matchingPrefix.length);
+		if (!filename || filename === '.' || filename === '..' || path.basename(filename) !== filename || filename.includes('\\')) {
+			return false;
+		}
+		return path.join(nconf.get('upload_path'), 'profile', filename);
+	}
+
+	async function removeFile(filename) {
+		try {
+			await fs.promises.unlink(filename);
+		} catch (err) {
+			if (err.code !== 'ENOENT') {
+				throw err;
+			}
+		}
+	}
+
+	function profileFilenamePattern(uid, type) {
+		if (!/^\d+$/.test(String(uid)) || Number(uid) <= 0) {
+			throw new Error('[[error:invalid-uid]]');
+		}
+		return new RegExp(`^${uid}-profile${type}(?:-\\d+)?\\.(?:png|jpeg|jpg|bmp)$`);
+	}
+
+	async function localProfilePaths(uid, type) {
+		const pattern = profileFilenamePattern(uid, type);
+		const folder = path.join(nconf.get('upload_path'), 'profile');
+		let names;
+		try {
+			names = await fs.promises.readdir(folder);
+		} catch (err) {
+			if (err.code === 'ENOENT') {
+				return [];
+			}
+			throw err;
+		}
+		return names.filter(name => pattern.test(name)).map(name => path.join(folder, name));
+	}
+
+	function getLocalProfilePath(uid, type) {
+		const pattern = profileFilenamePattern(uid, type);
+		const folder = path.join(nconf.get('upload_path'), 'profile');
+		try {
+			const name = fs.readdirSync(folder).find(name => pattern.test(name));
+			return name ? path.join(folder, name) : false;
+		} catch (err) {
+			if (err.code === 'ENOENT') {
+				return false;
+			}
+			throw err;
+		}
+	}
+
+	User.getLocalCoverPath = uid => getLocalProfilePath(uid, 'cover');
+	User.getLocalAvatarPath = uid => getLocalProfilePath(uid, 'avatar');
+
+	async function removeProfileFiles(uid, type, url) {
+		const paths = await localProfilePaths(uid, type);
+		const urlPath = localProfileUrlPath(url);
+		if (urlPath) {
+			paths.push(urlPath);
+		}
+		await Promise.all([...new Set(paths)].map(removeFile));
+	}
+
